using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;
public static class BlendCaveHillsideEdge{public static string Main(){var road=UnityEngine.Object.FindAnyObjectByType<RaceDirector>().road;road.Initialize();var samples=new List<Vector3>();for(float s=0;s<road.Length;s+=1)samples.Add(road.At(s,out _));var objects=new[]{GameObject.Find("Ground_Echo wooded hillside"),GameObject.Find("Echo eroded hillside face 0"),GameObject.Find("Echo eroded hillside face 140")};var cols=objects.Select(g=>g.GetComponent<Collider>()).ToArray();foreach(var g in objects){var m=g.GetComponent<MeshFilter>().sharedMesh;var v=m.vertices;for(int i=0;i<v.Length;i++){var p=v[i];float d=samples.Min(q=>Vector2.Distance(new(q.x,q.z),new(p.x,p.z)));if(d>=12)continue;float y=Physics.RaycastAll(new(p.x,200,p.z),Vector3.down,300,1).Where(h=>h.collider.name.StartsWith("Ground_")&&!cols.Contains(h.collider)).Select(h=>h.point.y).DefaultIfEmpty(p.y).Max();p.y=Mathf.Min(p.y,y-.3f);v[i]=p;}m.vertices=v;m.RecalculateNormals();m.RecalculateBounds();EditorUtility.SetDirty(m);g.GetComponent<MeshCollider>().sharedMesh=null;g.GetComponent<MeshCollider>().sharedMesh=m;}EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();return "Exposed border triangles buried into original road shoulder";}}
